import React, { useState } from "react";
import Navigation from "../components/nav";
import data from "../data/data.json";
import Logo from "../components/logo";
import { graphql } from "gatsby";
import images from "../images";
import PartnersForm from "../components/partnersForm";
import { useTranslation } from "gatsby-plugin-react-i18next";


export default function Partners() {
    const [currentYear, setYear] = useState<number | null>(null);
    const [isMobile, setIsMobile] = useState(false);
    const { t } = useTranslation();

    React.useEffect(() => {
        setYear(new Date().getFullYear());
    }, []);

    React.useEffect(() => {
        if (typeof window === "undefined") return;
        const media = window.matchMedia("(max-width: 640px)");
        const update = () => setIsMobile(media.matches);
        update();
        if (media.addEventListener) {
            media.addEventListener("change", update);
            return () => media.removeEventListener("change", update);
        }
        media.addListener(update);
        return () => media.removeListener(update);
    }, []);
  return (
    <section className="flex min-h-screen flex-col justify-between bg-DarkGreen">
      <Navigation />
      <section
        className={`${styles.container} bg-DarkGreen relative h-full pb-16 bg-cover`}
        id={"start"}
        style={{
          backgroundImage: `url(${
            isMobile
              ? images.partners_background_mob.src
              : images.partners_background_desk.src
          })`,
          backgroundRepeat: "no-repeat",
          backgroundPosition: "bottom center",
        }}
      >
        {/* Gradient overlay */}
        <div className="absolute bottom-[15%] left-0 right-0 h-[85%] bg-gradient-to-b from-transparent to-DarkGreen opacity-100 pointer-events-none z-10" />
        {/* Frame oscuro sólido del 15% inferior */}
        <div className="absolute bottom-0 left-0 right-0 h-[15%] bg-DarkGreen pointer-events-none z-10" />

        <article className="flex flex-col sm:flex-row w-full h-full px-0">
            <h2 className="text-white uppercase mt-20 sm:mt-64 title-mob sm:title relative z-20">{t("partners.title")}</h2>
          <div className="max-w-[1720px] w-full pt-20 sm:pt-64 h-full items-start justify-end flex">
            <div className=" flex justify-end items-center mt-6 px-2 sm:px-6 py-2 sm:py-6 rounded-lg bg-GrayText relative z-20">
                <PartnersForm />
            </div>
          </div>
        </article>
      </section>
      <footer className={styles.footerContainer}>
        <div className="flex flex-col sm:flex-row  w-full">
          <div className="flex flex-col w-[75px] sm:w-[123px] self-center">
            <Logo />
          </div>

          <div className="flex flex-col w-full justify-end">
            <div
              className={`justify-end py-6 px-4 text-[12px] text-center sm:text-end text-LightGrayText uppercase`}
            >
              &copy; {currentYear} {data?.name}
            </div>
          </div>
        </div>
      </footer>
    </section>
  );
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "w-full px-5 sm:px-16",
  section:
    "flex h-96 bg-primary my-8 w-full border border-primary rounded-lg shadow-md",
  title: "head-3 sm:head-1 text-Tofu",
  footerContainer:
    "flex flex-col text-light w-full px-7 bg-DarkGreen pt-20 sm:py-0",
};
